
const IMG = {
  bgWar: 'data:image/png;base64,', bgCity: 'data:image/png;base64,', bgValley: 'data:image/png;base64,',
  dragon: 'data:image/png;base64,', portrait: 'data:image/png;base64,',
  kobold: 'data:image/png;base64,', minotaur: 'data:image/png;base64,', chest: 'data:image/png;base64,',
  star: 'data:image/png;base64,', food: 'data:image/png;base64,', villager: 'data:image/png;base64,',
  swords: 'data:image/png;base64,', helm: 'data:image/png;base64,', hammer: 'data:image/png;base64,',
  wheat: 'data:image/png;base64,', scroll: 'data:image/png;base64,', castle: 'data:image/png;base64,',
  cog: 'data:image/png;base64,', pyreth: 'data:image/png;base64,', rodain: 'data:image/png;base64,',
  mirael: 'data:image/png;base64,', kael: 'data:image/png;base64,', lirae: 'data:image/png;base64,',
  folk: 'data:image/png;base64,', folkCarry: 'data:image/png;base64,', dwarf: 'data:image/png;base64,',
  elf: 'data:image/png;base64,', stripForest: 'data:image/png;base64,', goblin: 'data:image/png;base64,',
};
const img = (k, alt, style) => `<img class="px" src="${IMG[k]}" alt="${alt || ''}" style="${style || ''}">`;

// ---- shared pieces --------------------------------------------------------------------------
const topbar = (o = {}) => `
  <div class="topbar">
    <div class="res">${img('star', 'Renown')}<span style="color:#ffe2a0">${o.renown || '48.25'}</span></div>
    ${o.noFood ? '' : `<div class="res">${img('food', 'Food')}<span>${o.food || '140'}</span></div>`}
    <span style="flex:1"></span>
    <button class="iconbtn step" data-go="journal" aria-label="Open journal"><span class="step">${img('scroll', '', 'width:34px;height:34px')}</span></button>
  </div>`;
const objective = (text, prog, top = 72) => `
  <div class="ribbon" style="top:${top}px">
    <span class="scale" style="width:28px;height:32px;background:var(--ink);display:flex;align-items:center;justify-content:center;flex-shrink:0">${img('swords', '', 'width:20px;height:20px;margin-top:-4px')}</span>
    <b class="ol1">${text}</b><span class="num">${prog}</span>
  </div>`;
const tabs = (on, o = {}) => {
  const t = [['draconia', 'Draconia', 'castle'], ['warfront', 'Warfront', 'swords'], ['forage', 'Forage', 'wheat'], ['settings', 'Settings', 'cog']];
  return `<nav class="tabs" aria-label="Main tabs">${t.map(([id, label, icon]) => {
    const locked = o.locked && (id === 'draconia' || id === 'forage');
    return `<button class="tab ${on === id ? 'on' : ''}" data-go="${locked ? 'locked' : id}" ${on === id ? 'aria-current="page"' : ''}>
      <span class="gem scale"><span class="scale">${locked ? '<svg aria-hidden="true" width="18" height="20" viewBox="0 0 9 10" style="shape-rendering:crispEdges"><path fill="#b8ac98" d="M2 0h5v1h1v3h1v6H0V4h1V1h1zm1 1v3h3V1z"/></svg>' : img(icon)}</span></span>
      <b>${locked ? 'Locked' : label}</b>
      ${!locked && id === 'draconia' && o.dot ? '<i class="dot" aria-label="Something to build"></i>' : ''}
      ${!locked && id === 'forage' && o.bang ? '<i class="bang" aria-label="Food warning">!</i>' : ''}
    </button>`;
  }).join('')}</nav>`;
};
const bar = (pct, fill, h = 16, txt = '') => `<div class="bar step" style="height:${h}px"><div><i style="width:${pct}%;background:${fill}"></i>${txt}</div></div>`;
const gbtn = (label, go, cls = '') => `<button class="gbtn step ${cls}" ${go ? `data-go="${go}"` : ''}><span class="step">${label}</span></button>`;
const sbtn = (label, go, cls = '') => `<button class="sbtn step ${cls}" ${go ? `data-go="${go}"` : ''}><span class="step">${label}</span></button>`;
const qbtn = (label, go, cls = '') => `<button class="qbtn step ${cls}" ${go ? `data-go="${go}"` : ''}><span class="step">${label}</span></button>`;
const lock = (txt) => `<span class="lockbtn step">LOCKED · ${txt}</span>`;
const stats = (items) => `<div class="stats step">${items.map(([v, l]) => `<div><span class="num">${v}</span><small>${l}</small></div>`).join('')}</div>`;
const card = (icon, title, sub, right) => `<div class="card step">${icon ? img(icon) : ''}<div class="t"><b>${title}</b><span>${sub}</span></div>${right || ''}</div>`;
const sheet = (title, sub, body, icon) => `<div class="dim" data-go="back"></div>
  <div class="sheet step"><div class="in step">
    <div class="shead">${icon ? img(icon, '', 'width:40px;height:40px') : ''}<div><h3>${title}</h3>${sub ? `<div class="sub">${sub}</div>` : ''}</div>
      <button class="iconbtn step x" data-go="back" aria-label="Close" style="width:40px;height:40px"><span class="step"><svg aria-hidden="true" width="14" height="14" viewBox="0 0 7 7" style="shape-rendering:crispEdges"><path fill="#f5ecd8" d="M0 0h2v1h1v1h1V1h1V0h2v2H6v1H5v1h1v1h1v2H5V6H4V5H3v1H2v1H0V5h1V4h1V3H1V2H0z"/></svg></span></button></div>
    ${body}</div></div>`;
const sheetRes = () => `<div class="pills"><span class="pill">${'48.25'} renown</span><span class="pill">140 food</span><span class="pill">18 idle</span></div>`;
const modal = (top, inner) => `<div class="dim"></div><div class="modal step" style="top:${top}px"><div class="in step">${inner}</div></div>`;

// ---- the Warfront scene (reused by overlays) --------------------------------------------------
function warfront(o = {}) {
  const chrome = !o.opening;
  return `
  ${img('bgWar', '', '', '').replace('class="px"', 'class="px bg"')}
  ${chrome ? topbar() + objective('Forge 2 swords', '1/2') : ''}
  ${chrome ? `<div class="abs" style="left:14px;right:14px;top:122px;display:flex;flex-wrap:wrap;gap:6px">
     <div class="chip">${img('villager')}<span class="num">18</span><span>villagers</span></div>
     <div class="chip">${img('swords')}<span class="num" style="color:var(--danger)">6</span><span>fighters</span></div>
     <div class="chip">${img('hammer')}<span class="num">2</span><span>repairing</span></div>
     <div class="chip">${img('helm')}<span class="num" style="color:var(--steel)">4</span><span>fighting</span></div>
   </div>` : ''}
  ${chrome ? `<p class="abs ol1" style="left:24px;right:24px;top:196px;margin:0;text-align:center;font-weight:800;font-style:italic;font-size:14px;color:var(--gold)">"The dark has teeth tonight. So do we."</p>` : ''}
  <div class="abs" style="left:44px;right:44px;top:${chrome ? 222 : 120}px">
    ${chrome ? `<div class="ol" style="text-align:center;font-family:var(--f-display);font-weight:900;font-size:18px;letter-spacing:1px;margin-bottom:4px">Kobold</div>` : ''}
    ${bar(60, 'linear-gradient(#ff8a7a 0 4px,#d43a3a 4px)', 22, '<span class="ol1 num" style="position:absolute;right:6px;top:-1px;font-size:13px">3 / 5</span>')}
  </div>
  <button class="abs" data-strike aria-label="Strike the kobold" style="all:unset;position:absolute;cursor:pointer;left:70px;top:${chrome ? 262 : 160}px;width:250px;height:250px;display:flex;align-items:flex-end;justify-content:center">
    <span style="position:absolute;left:50%;bottom:10px;width:180px;height:30px;transform:translateX(-50%);border-radius:50%;background:radial-gradient(ellipse,rgba(0,0,0,0.6),transparent 70%)"></span>
    ${img('kobold', '', 'position:relative;width:170px;animation:bob 2.2s ease-in-out infinite')}
  </button>
  <span aria-hidden="true" class="abs" style="left:0;top:${chrome ? 470 : 520}px;width:240px;height:140px;background:radial-gradient(ellipse,rgba(255,140,50,0.30),transparent 65%)"></span>
  ${img('dragon', 'You, the dragon, perched on the gate (stand-in art)', `position:absolute;left:-6px;top:${chrome ? 448 : 448}px;width:256px;height:256px;animation:breathe 3.2s ease-in-out infinite`)}
  ${chrome ? `
  <div class="abs" style="left:14px;right:14px;top:596px;display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;justify-content:flex-end">
    <span class="ol1 num" style="font-size:15px">Wall 64/100</span>
    <span class="ol1" style="font-weight:900;font-size:14px;color:var(--warn)">cracking</span>
    <span class="ol1 num" style="font-size:13px;color:var(--muted)">Horde level 3</span>
  </div>` : ''}
  <div class="abs" style="left:14px;right:14px;top:${chrome ? 620 : 700}px;display:flex;align-items:center;gap:8px">
    <span class="ol1" style="font-family:var(--f-display);font-weight:900;font-size:14px;letter-spacing:2px;color:var(--gold-hi)">GATE</span>
    <div style="flex:1">${bar(64, 'linear-gradient(#ffe08a 0 4px,#e8ac36 4px)', 18)}</div>
  </div>
  ${chrome ? `
  <div class="abs" style="left:0;right:0;top:652px;display:flex;justify-content:center;gap:34px">
    <button class="orb" data-go="rally"><span class="disc" style="background:radial-gradient(circle at 40% 30%,#cfe2ff,#5a86c0)">${img('swords')}</span><span class="lbl ol1">RALLY</span><span class="cost num">1.85 renown</span></button>
    <button class="orb"><span class="disc" style="background:radial-gradient(circle at 40% 30%,#e8e0c8,#8a8270)">${img('hammer')}</span><span class="lbl ol1">REPAIR</span><span class="cost num">0.95 renown</span></button>
  </div>
  <div class="abs" style="left:10px;right:10px;top:728px;display:flex;align-items:center;justify-content:space-between;gap:6px">
    <span class="ol1 num" style="font-size:13px;color:var(--muted)">37 monsters slain</span>
    <button class="chip" data-go="claws" style="all:unset;cursor:pointer" aria-label="Your claws: Hooked, 3 per tap. Can sharpen."><span class="chip" style="padding-right:14px">${img('hammer')}<span style="color:var(--gold)">Hooked, <b class="num" style="color:var(--cream)">3</b> per tap ▲</span></span></button>
    <span class="ol1 num" style="font-size:13px;color:var(--steel)">army 2.40 dmg/s</span>
  </div>` : ''}
  ${chrome ? tabs('warfront', { dot: true }) : ''}`;
}

// ---- Draconia map -------------------------------------------------------------------------------
function node(x, y, name, status, opts = {}) {
  const fog = opts.fog;
  return `<button class="abs" data-go="${fog ? '' : opts.go || ''}" ${fog ? 'aria-disabled="true"' : ''} aria-label="${fog ? 'Undiscovered building' : name + ', ' + status}" style="all:unset;position:absolute;left:${x}px;top:${y}px;cursor:${fog ? 'default' : 'pointer'};transform:translateX(-50%);${fog ? 'opacity:0.4' : ''}">
    <span class="step" style="display:block;background:var(--ink);padding:2px;white-space:nowrap;position:relative">
      <span class="step" style="display:flex;flex-direction:column;align-items:center;padding:4px 10px;background:linear-gradient(#4a3a2a,#2a1e16);box-shadow:inset 0 2px 0 ${opts.edge || 'var(--gold)'}">
        <span style="font-weight:900;font-size:13px;color:${fog ? 'var(--muted)' : '#ffe2a0'}">${fog ? '???' : name}</span>
        <span class="num" style="font-size:11px;color:${opts.statusColor || 'var(--muted)'}">${fog ? (opts.soon ? 'Coming soon' : 'Undiscovered') : status}</span>
      </span>
    </span>
    ${opts.badge ? '<i class="abs" style="right:-4px;top:-4px;width:12px;height:12px;background:var(--danger);box-shadow:0 0 0 2px var(--ink);transform:rotate(45deg)" aria-hidden="true"></i>' : ''}
  </button>`;
}
const zone = (x, y, t) => `<span class="abs ol1" style="left:${x}px;top:${y}px;font-family:var(--f-num);font-size:11px;letter-spacing:2px;color:var(--muted)">◆ ${t}</span>`;
function draconia() {
  return `${img('bgCity').replace('class="px"', 'class="px bg"')}
  ${topbar()}${objective('Forge 2 swords', '1/2')}
  <div class="abs" style="left:0;right:0;top:118px;text-align:center"><span class="ol" style="font-family:var(--f-display);font-weight:900;font-size:26px;letter-spacing:6px;color:var(--gold-hi)">DRACONIA</span></div>
  ${zone(150, 162, 'THE KEEP')}
  ${node(196, 278, 'Draconia Keep', 'Offline: 5 hours', { go: 'keep' })}
  ${zone(20, 308, 'INNER WARD')}
  ${node(258, 320, 'The Librarium', '4/15 researched', { go: 'librarium', edge: '#38bdf8' })}
  ${node(130, 352, 'Housing', '', { fog: true, soon: true })}
  ${zone(20, 410, 'CRAFT WARD')}
  ${node(80, 444, "Ranger's Lodge", 'Lv2 · 3/6 rangers', { go: 'lodge', edge: '#4ade80' })}
  ${node(312, 498, 'The Forge', '1 swords, 0 shields', { go: 'forge', edge: '#f59e0b' })}
  ${zone(20, 540, 'OUTER WARD')}
  ${node(84, 600, 'The Garrison', 'Lv2 · 4/8 soldiers', { go: 'garrison', edge: '#f87171', badge: true })}
  ${node(250, 610, "Wayfinder's Outpost", 'Lv1 · 2/4 wayfinders', { go: 'outpost', edge: '#60a5fa' })}
  ${node(170, 506, "Wizard's Tower", '', { fog: true, soon: true })}
  ${zone(20, 668, 'CITY EDGE')}
  ${node(120, 696, 'Tower West', '', { fog: true, soon: true })}
  ${node(270, 696, 'Tower East', '', { fog: true, soon: true })}
  ${tabs('draconia', { dot: true })}`;
}

// ---- Forage -----------------------------------------------------------------------------------
function forage() {
  return `<div class="bg" style="background:linear-gradient(#0d1410,#07050c 60%)"></div>
  ${img('bgValley', '', 'position:absolute;left:0;top:60px;width:390px;height:288px;opacity:0.85')}
  ${topbar({ noFood: true })}${objective('Fill the stores', '140/200')}
  <div class="abs" style="left:0;right:0;top:124px;display:flex;flex-direction:column;align-items:center;gap:2px">
    <span style="display:flex;align-items:center;gap:8px">${img('food', '', 'width:48px;height:48px')}<span class="ol num" style="font-size:44px">140</span></span>
    <span class="ol1" style="font-weight:800;font-size:13px;color:var(--muted)">food stores (granary holds 500)</span>
    <span class="pill" style="background:#1f3a24;color:#86efac;margin-top:4px">+10% forage bonus</span>
  </div>
  <div class="abs step" style="left:16px;right:16px;top:236px;background:rgba(14,9,18,0.9);padding:10px 12px;display:flex;flex-direction:column;gap:4px">
    <span style="font-weight:900;font-size:14px;color:var(--danger)">Stores are falling</span>
    <span class="num" style="font-size:13px;color:var(--cream)">Each meal: -12 eaten, +9 gathered</span>
    <span class="num" style="font-size:13px;color:var(--gold)">Next meal in 0:42</span>
  </div>
  <div class="abs" style="left:16px;right:16px;top:330px;display:flex;flex-direction:column;gap:6px">
    <span class="slabel ol1">FIGHTERS' RATIONS</span>
    <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:4px">
      ${['None', 'Quarter', 'Half', 'Full', 'Double'].map((r, i) => `<span class="step" style="padding:7px 0;text-align:center;font-weight:900;font-size:12px;background:${i === 3 ? 'var(--gold)' : 'var(--stone)'};color:${i === 3 ? '#3a1d06' : (i === 1 || i === 4 ? 'var(--muted)' : 'var(--cream)')}">${r}${(i === 1 || i === 4) ? ' (locked)' : ''}</span>`).join('')}
    </div>
    <span class="ol1" style="font-weight:700;font-size:12px;color:var(--muted)">Quarter rations: research Lean Rations in the Librarium.</span>
  </div>
  <button class="orb abs" style="left:50%;top:430px;transform:translateX(-50%)" data-forage aria-label="Forage for food">
    <span class="disc" style="width:150px;height:150px;background:radial-gradient(circle at 40% 30%,#bff5c8,#2f8a44)">${img('wheat', '', 'width:80px;height:80px')}</span>
    <span class="lbl ol1" style="font-size:20px">FORAGE</span>
  </button>
  <div class="abs" style="left:0;right:0;top:622px;display:flex;justify-content:center;gap:40px">
    <button class="orb"><span class="disc" style="width:60px;height:60px;background:radial-gradient(circle at 40% 30%,#cfe2ff,#5a86c0)">${img('villager', '', 'width:34px;height:34px')}</span><span class="lbl ol1" style="font-size:13px">TRAIN</span><span class="cost num">0.80 renown · 3/6</span></button>
    <button class="orb"><span class="disc" style="width:60px;height:60px;background:radial-gradient(circle at 40% 30%,#cfe2ff,#5a86c0)">${img('scroll', '', 'width:34px;height:34px')}</span><span class="lbl ol1" style="font-size:13px">RECRUIT</span><span class="cost num">1.5 renown · 2/4</span></button>
  </div>
  <div class="abs" style="left:14px;right:14px;top:730px;display:flex;justify-content:space-between;align-items:center">
    <span class="ol1 num" style="font-size:12px;color:var(--muted)">212 foraging trips, 1,840 food gathered in all</span>
    <span class="pill" style="background:#1f3a24;color:#86efac">+2 per tap</span>
  </div>
  ${tabs('forage', { dot: true, bang: true })}`;
}

// ---- Settings ---------------------------------------------------------------------------------
function settings(tab = 'Settings') {
  const body = tab === 'Settings' ? `
    <span class="slabel">SOUND &amp; VIBRATION</span>
    ${card('', 'Music', 'Volume 70%', '<span class="pill">Mute</span>')}
    ${card('', 'Sound Effects', 'Volume 85%', '<span class="pill">Mute</span>')}
    ${card('', 'Vibration', 'Buzz on taps, purchases and events', '<span class="pill on">On</span>')}
    <span class="slabel">CREDITS</span>
    ${card('scroll', 'Refusing The Ultimatum', 'Main theme · Arthur Vyncke · CC BY-SA 3.0')}
    <span class="slabel">DANGER ZONE</span>
    ${qbtn('Reset Game', 'reset', 'full')}
    <span class="sub" style="text-align:center">This will erase all progress</span>` : `
    <span class="slabel">ECONOMY</span>${card('star', 'Renown 48.25', 'Total Earned 612.40 · Total Spent 564.15')}
    <span class="slabel">COMBAT</span>${card('swords', 'Monsters Defeated 37', 'Total Clicks 1,204 · Tap Damage 3')}
    <span class="slabel">ARMY</span>${card('helm', 'Active Soldiers 4', 'Soldiers Trained 5 · Conscripts Trained 5 · Barracks Level 2')}
    <span class="slabel">DRACONIA</span>${card('food', 'Food 140', 'Villagers 18 · Food/check -12 every 60s')}
    <span class="slabel">SESSION</span>${card('', 'Time Played', '3h 12m')}`;
  return `<div class="bg" style="background:linear-gradient(#1a1420,#0c0910)"></div>
  ${topbar()}${objective('Forge 2 swords', '1/2')}
  <div class="abs" style="left:16px;right:16px;top:124px;bottom:86px;overflow-y:auto;display:flex;flex-direction:column;gap:10px;padding-bottom:12px">
    <div class="pills">${['Settings', 'Stats'].map((t) => `<button class="pill ${t === tab ? 'on' : ''}" style="all:unset;cursor:pointer" data-go="${t === 'Settings' ? 'settings' : 'stats'}"><span class="pill ${t === tab ? 'on' : ''}">${t}</span></button>`).join('')}</div>
    ${body}
  </div>
  ${tabs('settings', { dot: true })}`;
}

// ---- building interiors (bottom sheets over the map) ------------------------------------------
