const byId = Object.fromEntries(SCREENS.map((s) => [s.id, s]));
const EXTRA = { rally: { render: overlays.rally, back: 'warfront' }, locked: { render: overlays.locked, back: 'warfront' } };

// ---- rendering and navigation -----------------------------------------------------------------
const phone = document.getElementById('phone');
const nav = document.getElementById('nav');
const pick = document.getElementById('pick');
const notes = document.getElementById('notes');
let current = 'warfront';
let base = 'warfront';

function buildNav() {
  const groups = [...new Set(SCREENS.map((s) => s.group))];
  nav.innerHTML = groups.map((g) => `<div><h2>${g}</h2><ul>${SCREENS.filter((s) => s.group === g).map((s) => `<li><button data-nav="${s.id}">${s.title}</button></li>`).join('')}</ul></div>`).join('');
  pick.innerHTML = groups.map((g) => `<optgroup label="${g}">${SCREENS.filter((s) => s.group === g).map((s) => `<option value="${s.id}">${s.title}</option>`).join('')}</optgroup>`).join('');
}
function show(id) {
  const s = byId[id] || EXTRA[id];
  if (!s) return;
  if (byId[id]) { current = id; if (!['claws', 'journal'].includes(id)) base = id; }
  phone.innerHTML = s.render();
  if (byId[id]) {
    nav.querySelectorAll('button').forEach((b) => b.setAttribute('aria-current', b.dataset.nav === id ? 'true' : 'false'));
    pick.value = id;
    notes.innerHTML = `<h2>${s.title}</h2><span class="src">${s.src}</span><ul>${s.notes.map((n) => `<li>${n}</li>`).join('')}</ul>`;
    try { history.replaceState(null, '', '#' + id); } catch (e) {}
  }
}
phone.addEventListener('click', (e) => {
  const strike = e.target.closest('[data-strike]');
  if (strike) {
    const r = phone.getBoundingClientRect();
    const k = r.width / 390;
    const f = document.createElement('span');
    f.className = 'float';
    f.textContent = '-3';
    f.style.left = (e.clientX - r.left) / k + 'px';
    f.style.top = (e.clientY - r.top) / k - 20 + 'px';
    phone.appendChild(f);
    setTimeout(() => f.remove(), 900);
    return;
  }
  const fg = e.target.closest('[data-forage]');
  if (fg) {
    const f = document.createElement('span');
    f.className = 'float'; f.textContent = '+2'; f.style.color = '#86efac'; f.style.left = '195px'; f.style.top = '440px';
    phone.appendChild(f); setTimeout(() => f.remove(), 900); return;
  }
  const go = e.target.closest('[data-go]');
  if (!go || !go.dataset.go) return;
  const to = go.dataset.go;
  if (to === 'back') { show(['claws', 'journal'].includes(current) ? 'warfront' : (byId[current] && byId[current].group === 'Draconia buildings' ? 'draconia' : base)); return; }
  show(to);
});
nav.addEventListener('click', (e) => { const b = e.target.closest('[data-nav]'); if (b) show(b.dataset.nav); });
pick.addEventListener('change', () => show(pick.value));

function fit() {
  const wrap = document.getElementById('wrap');
  const k = Math.min(1, wrap.clientWidth / 390);
  phone.style.transform = `scale(${k})`;
  wrap.style.height = 844 * k + 'px';
}
window.addEventListener('resize', fit);
buildNav();
const start = (location.hash || '').slice(1);
show(byId[start] ? start : 'warfront');
fit();
